import os
for r,ds,fs in os.walk('studies'):
 for f in fs: print(os.path.join(r,f))

import gzip,glob,csv
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 for line in gzip.open(f,'rt'):
  if line.startswith('!Sample_'):
   row=next(csv.reader([line],delimiter='\t'))
   if any(x in row[0] for x in ['title','geo_accession','source_name','characteristics','treatment_protocol','description','extract_protocol','data_processing']):print(row)

